D={
70023:("He, she, it","Pessoas: **he** (menino/homem) e **she** (menina/mulher). Coisas e animais: **it**. *The boy has a bike. He is fast. It is red.*",[("The boy next door has a bike.","O menino ao lado tem uma bicicleta."),("{{He}} is nine.","Ele tem nove anos."),("{{It}} is red.","Ela é vermelha."),("{{She}} lives near the fence.","Ela mora perto da cerca.")],"Qual pronome substitui a bike?",["he","she","it"],2,"Coisa: it."),
30012:("Falar de uma foto","Para descrever uma foto: **In this photo, …** e **There is / There are**. *In this photo there is a puppy.*",[("{{In this photo}}, there is a puppy.","Nesta foto, há um cachorrinho."),("{{It is}} on vacation.","Ele está de férias."),("The sun {{is}} bright.","O sol está forte."),("I love this camera.","Eu adoro esta câmera.")],"Como começar a descrever uma foto?",["In this photo, …","At this photo, …","Of this photo, …"],0,"In this photo, … é o padrão."),
70024:("Plural: -s e -ies","Plural comum: **+s** (*paw → paws*). Palavras com consoante + **y** trocam por **-ies**: *puppy → puppies, kitten → kittens*.",[("One {{puppy}}, two {{puppies}}.","Um cachorrinho, dois cachorrinhos."),("One {{paw}}, four {{paws}}.","Uma pata, quatro patas."),("The {{kittens}} have soft fur.","Os gatinhos têm pelo macio."),("The mouse has a long tail.","O rato tem um rabo comprido.")],"Plural de puppy:",["puppys","puppies","puppyes"],1,"Consoante + y: troque por -ies."),
10153:("We are, they are","**We are** = nós somos, **they are** = eles/elas são. Na fala: **we're, they're**. Serve para pessoas e coisas.",[("{{We are}} a team.","Somos um time."),("{{They are}} our fans.","Eles são nossos torcedores."),("{{We're}} in the field.","Estamos no campo."),("{{They're}} in blue uniforms.","Eles estão de uniforme azul.")],"Qual é a forma curta de they are?",["they're","there","theyre"],0,"They are → they're."),
70025:("We are + ação","Com **we are** e **they are**, falamos do grupo. *We are in the park. They are with the coach.* O verbo be não muda.",[("{{We are}} in the park.","Estamos no parque."),("{{They are}} with the coach.","Eles estão com o treinador."),("Pass the ball!","Passe a bola!"),("Goal!","Gol!")],"Complete: “The players ___ ready.”",["is","are","am"],1,"Plural: are."),
30013:("We / They no trabalho","Para falar de um grupo: **We are early. They are late.** Em reuniões, **we** inclui você e **they** exclui você.",[("{{We are}} early for the meeting.","Estamos adiantados para a reunião."),("{{They are}} late.","Eles estão atrasados."),("The agenda is on the screen.","A pauta está na tela."),("Take a note, please.","Anote, por favor.")],"Se você faz parte do grupo, use…",["we","they","he"],0,"We inclui você."),
70026:("We / They em casa","**We** e **they** servem para casa também: *We are in the kitchen. They are on a break.* Para pedir algo: **Can we…?**",[("{{We are}} in the kitchen.","Estamos na cozinha."),("{{They are}} on a break.","Eles estão em pausa."),("{{Can we}} have some coffee?","Podemos tomar um café?"),("Here is your mug.","Aqui está sua caneca.")],"Como pedir “Podemos tomar café?”",["Can we have coffee?","We can coffee?","Can coffee we?"],0,"Can we + verbo."),
910006:("And, but, or","**And** soma, **but** contrasta, **or** oferece escolha. *I'm tired but ready.* *Tea or coffee?*",[("Coffee {{and}} a smoothie.","Café e uma vitamina."),("I'm tired, {{but}} I'm ready.","Estou cansado, mas pronto."),("Tea {{or}} coffee?","Chá ou café?"),("Not now.","Agora não.")],"Qual conector indica contraste?",["and","but","or"],1,"But = mas."),
10154:("Perguntas com be","Para perguntar com be, **troque a ordem**: *You are late.* → **Are you late?** O verbo vem antes do sujeito.",[("{{Are you}} at the airport?","Você está no aeroporto?"),("{{Is the taxi}} here?","O táxi está aqui?"),("{{Is it}} on the meter?","Está no taxímetro?"),("Yes, it is.","Sim, está.")],"Como perguntar “O táxi está aqui?”",["The taxi is here?","Is the taxi here?","Does the taxi here?"],1,"Is + sujeito + lugar?"),
70027:("Perguntas com be","A resposta curta repete o verbo: **Is it far? — Yes, it is.** *No, it isn't.* Nunca *Yes, it's*.",[("{{Is the bridge}} open?","A ponte está aberta?"),("No, {{it isn't}}.","Não."),("{{Are we}} late?","Estamos atrasados?"),("Yes, {{we are}}.","Sim, estamos.")],"Resposta curta de Are we late? (sim):",["Yes, we're.","Yes, we are.","Yes, we do."],1,"Resposta curta de sim usa a forma inteira."),
30014:("Where is / Where are","**Where is** para um (*Where is gate 5?*) e **Where are** para vários (*Where are the gates?*).",[("{{Where is}} gate 5?","Onde fica o portão 5?"),("{{Where are}} the screens?","Onde ficam as telas?"),("It's at terminal B.","Fica no terminal B."),("Your flight is on time.","Seu voo está no horário.")],"Complete: “Where ___ my passport?”",["is","are","do"],0,"Passport é um: is."),
70028:("Where is / Where are","Perguntando por objetos da mala: **Where is my charger? Where are my pants?** Pessoal e plural concordam com o verbo.",[("{{Where is}} my umbrella?","Onde está meu guarda-chuva?"),("{{Where are}} my pants?","Onde estão minhas calças?"),("It's in the bag.","Está na mala."),("They're on the bed.","Estão na cama.")],"Plural: “Onde estão meus sapatos?”",["Where is my shoes?","Where are my shoes?","Where my shoes?"],1,"Shoes é plural: are."),
10155:("Yes, I am / No, I'm not","Respostas curtas com be: **Yes, I am. / No, I'm not.** Não se diz *Yes, I'm*. O não pode ser **I'm not**.",[("Are you hungry? {{Yes, I am}}.","Você está com fome? Sim."),("Are you tired? {{No, I'm not}}.","Você está cansado? Não."),("I'm thirsty too.","Também estou com sede."),("Let's eat!","Vamos comer!")],"Resposta curta de sim a Are you bored?",["Yes, I'm.","Yes, I am.","Yes, I do."],1,"Yes, I am."),
70029:("Sentir frio, sono","Em inglês, frio, sono e fome usam **be**: *I'm cold. I'm sleepy.* Em português dizemos “estou com frio” — lá é só **be + adjetivo**.",[("I {{am cold}}.","Estou com frio."),("She {{is sleepy}}.","Ela está com sono."),("We {{are full}}.","Estamos satisfeitos."),("It's cozy by the fire.","É aconchegante perto da lareira.")],"Como se diz “Estou com sono”?",["I have sleepy.","I am sleepy.","I sleepy."],1,"be + adjetivo."),
30015:("Yes, we are / No, he isn't","Respostas curtas mudam o sujeito: **Yes, we are. / No, he isn't. / Yes, they are.** Sempre com o verbo do pronome.",[("Are you nervous? {{Yes, we are}}.","Vocês estão nervosos? Sim."),("Is he upset? {{No, he isn't}}.","Ele está chateado? Não."),("Are they hot? {{Yes, they are}}.","Eles estão com calor? Sim."),("The doctor is calm.","O médico está calmo.")],"Resposta curta de Is she safe? (não):",["No, she isn't.","No, she aren't.","No, she not."],0,"She → isn't."),
70030:("I can't wait!","**I can't wait!** = mal posso esperar. Combina com *be excited*, *be busy*, *be sick*. Cada um usa **be**.",[("I'm {{excited}}!","Estou animado!"),("I {{can't wait}} for the holiday.","Mal posso esperar pelas férias."),("He's busy today.","Ele está ocupado hoje."),("What a surprise!","Que surpresa!")],"O que significa I can't wait?",["mal posso esperar","não posso ir","não sei"],0,"Expressão de entusiasmo."),
910007:("Because and so","**Because** dá o motivo: *I stay home because it's gloomy.* **So** dá o resultado: *It's gloomy, so I stay home.*",[("I'm cold {{because}} it's snowy.","Estou com frio porque está nevando."),("It's gloomy, {{so}} I stay home.","Está sombrio, então fico em casa."),("The weatherman is right.","O meteorologista está certo."),("That's the reason.","Esse é o motivo.")],"Qual conector dá o motivo?",["because","so","but"],0,"Because = porque."),
10156:("I'm not, it isn't","Para negar be, acrescente **not**: *I am not, it is not*. Na fala: **I'm not, it isn't, we aren't**.",[("I {{am not}} lost.","Não estou perdido."),("It {{isn't}} far.","Não é longe."),("The town {{isn't}} big.","A cidade não é grande."),("We {{aren't}} sure.","Não temos certeza.")],"Forma curta de it is not:",["it isn't","it'nt","its not"],0,"It isn't."),
70031:("Not yet / Never mind","**Not yet** = ainda não. **Never mind** = deixa pra lá. *The bakery isn't open yet.*",[("The bakery {{isn't}} open {{yet}}.","A padaria ainda não abriu."),("{{Not yet}}!","Ainda não!"),("{{Never mind}}.","Deixa pra lá."),("The market opens at nine.","O mercado abre às nove.")],"O que significa not yet?",["ainda não","nunca","agora"],0,"Not yet = ainda não."),
30016:("Lugares: isn't open","Para lugares fechados: **It isn't open.** Para horários: **It's open from nine to five.**",[("The bank {{isn't open}} today.","O banco não abre hoje."),("The mall {{is open}} until nine.","O shopping abre até as nove."),("There is a parking lot.","Há um estacionamento."),("The sidewalk is wide.","A calçada é larga.")],"Como dizer “O banco está fechado”?",["The bank isn't open.","The bank no open.","The bank not is."],0,"isn't open."),
70032:("Perto e longe","**Near** e **far**: *It's near. It isn't far.* Para direção: **around the corner**, **next block**.",[("The shop is {{near}}.","A loja é perto."),("It isn't {{far}}.","Não é longe."),("It's {{around the corner}}.","Fica virando a esquina."),("See the tower?","Vê a torre?")],"O que significa around the corner?",["virando a esquina","atrás da casa","em frente"],0,"Around the corner."),
10157:("This / That","**This** (aqui, perto) e **that** (lá, longe). *What's this? What's that?* A resposta: **It's a…**",[("{{What's this}}?","O que é isto?"),("{{It's}} a marker.","É um marcador."),("{{What's that}}?","O que é aquilo?"),("{{It's}} a folder.","É uma pasta.")],"Para perguntar sobre algo longe:",["What's this?","What's that?","What are those?"],1,"That = longe."),
70033:("This is / That is","**This** e **that** são singular; **these** e **those** são plural. *This is a ruler. These are crayons.*",[("{{This is}} a ruler.","Isto é uma régua."),("{{That is}} a toy.","Aquilo é um brinquedo."),("{{These are}} crayons.","Estas são giz de cera."),("Where is the glue?","Onde está a cola?")],"Plural de this:",["these","thats","this's"],0,"These."),
30017:("How much is it?","**How much is it?** (singular). **How much are they?** (plural). A resposta: **It's… / They're…**",[("{{How much is}} the lamp?","Quanto custa a luminária?"),("{{It's}} ten dollars.","São dez dólares."),("{{How much are}} the plants?","Quanto custam as plantas?"),("{{They're}} five dollars.","São cinco dólares.")],"Preço de vários itens:",["How much is these?","How much are they?","How many is?"],1,"Plural: How much are they?"),
70034:("Cheap e expensive","**Cheap** = barato, **expensive** = caro. *It's cheap. It's a discount!* Para dizer “muito”: **very, so, too**.",[("It is {{cheap}}.","É barato."),("It's {{very}} {{cheap}}.","É muito barato."),("There is a discount.","Há um desconto."),("I pay in cash.","Pago em dinheiro.")],"O que significa cheap?",["barato","caro","bonito"],0,"Cheap = barato."),
910008:("Have breakfast","Para refeições, use **have**: *have breakfast, have lunch, have dinner.* Não use *eat* com o nome da refeição.",[("I {{have breakfast}} at seven.","Tomo café da manhã às sete."),("We {{have lunch}} together.","Almoçamos juntos."),("They {{have dinner}} at eight.","Eles jantam às oito."),("I'm starving!","Estou morrendo de fome!")],"Qual está certa?",["I eat lunch the.","I have lunch.","I lunch have."],1,"have + refeição."),
10158:("These, those","**These** = estes/estas (perto). **Those** = aqueles/aquelas (longe). Para plurais: *These apples. Those peaches.*",[("{{These}} apples are red.","Estas maçãs são vermelhas."),("{{Those}} peaches are sweet.","Aqueles pêssegos são doces."),("What are {{these}}?","O que são estes?"),("What are {{those}}?","O que são aqueles?")],"Plural longe:",["this","that","those"],2,"Those."),
70035:("These are / Those are","**These are…** / **Those are…** + plural. *These are oranges. Those are potatoes.*",[("{{These are}} fresh oranges.","Estas são laranjas frescas."),("{{Those are}} potatoes.","Aquelas são batatas."),("How many pounds?","Quantos quilos?"),("Two pounds, please.","Dois quilos, por favor.")],"Complete: “___ are my keys.” (perto)",["These","This","Those"],0,"These are."),
30018:("Are these…? Yes, they are","Pergunta: **Are these sweet?** Resposta: **Yes, they are.** *No, they aren't.* Para plural, sempre **they**.",[("{{Are these}} bananas sweet?","Estas bananas são doces?"),("Yes, {{they are}}.","Sim."),("{{Are those}} pears fresh?","Aquelas peras estão frescas?"),("No, {{they aren't}}.","Não.")],"Resposta curta a Are these grapes sweet? (sim)",["Yes, these are.","Yes, they are.","Yes, it is."],1,"They are."),
70036:("Adjetivos de sabor","**Sweet** (doce), **sour** (azedo). *These lemons are sour.* Adjetivo depois do verbo be, sem -s.",[("The lemons {{are sour}}.","Os limões são azedos."),("The organic berries {{are sweet}}.","As frutas orgânicas são doces."),("Put them in the basket.","Coloque-as na cesta."),("Add some ice.","Acrescente gelo.")],"Complete: “Lemons ___.” (azedos)",["are sour","is sours","sour are"],0,"are + adjetivo."),
}
